WITH budget_lock AS MATERIALIZED (SELECT pg_advisory_xact_lock(hashtextextended('nikon-app-release-budget',0))), removed AS (DELETE FROM public.nikon_app_release_budgets b USING budget_lock WHERE b.budget_key LIKE 'file:ip:%' OR b.budget_key LIKE 'file:global:%' RETURNING b.budget_key,b.requests,b.bytes,b.expires_at) SELECT clock_timestamp() AS reset_at,current_setting('TimeZone') AS database_timezone,COALESCE((SELECT jsonb_agg(to_jsonb(removed) ORDER BY budget_key) FROM removed),'[]'::jsonb) AS removed_rows,(SELECT count(*) FROM removed) AS removed_bucket_count;
